import random

def matmul(A,B):
    return [[sum(A[i][k]*B[k][j] for k in range(len(B))) for j in range(len(B[0]))] for i in range(len(A))]
def transpose(A):
    return [[A[i][j] for i in range(len(A))] for j in range(len(A[0]))]
def matvec(A,v):
    return [sum(A[i][k]*v[k] for k in range(len(v))) for i in range(len(A))]
def ident(n):
    return [[1.0 if i==j else 0.0 for j in range(n)] for i in range(n)]

random.seed(1)
n,p = 5,8
phi=[[random.gauss(0,1) for _ in range(p)] for _ in range(n)]
K=matmul(phi,transpose(phi))
eta=0.05
T=[[ (1.0 if i==j else 0.0)-eta*K[i][j] for j in range(n)] for i in range(n)]
u0=[random.gauss(0,1) for _ in range(n)]
for t in (1,3,7):
    u=u0[:]
    for _ in range(t): u=matvec(T,u)
    P=ident(n)
    for _ in range(t): P=matmul(P,T)
    pw=matvec(P,u0)
    print('t=',t,' err=', max(abs(u[i]-pw[i]) for i in range(n)))

import math, random

def matmul(A,B):
    return [[sum(A[i][k]*B[k][j] for k in range(len(B))) for j in range(len(B[0]))] for i in range(len(A))]
def transpose(A):
    return [[A[i][j] for i in range(len(A))] for j in range(len(A[0]))]

def sym_eigs(A, sweeps=100):
    n=len(A); M=[r[:] for r in A]
    for _ in range(sweeps):
        off=0.0; p=0; q=1
        for i in range(n):
            for j in range(i+1,n):
                if abs(M[i][j])>off: off=abs(M[i][j]); p,q=i,j
        if off<1e-14: break
        app,aqq,apq=M[p][p],M[q][q],M[p][q]
        th=(aqq-app)/(2*apq); t=math.copysign(1,th)/(abs(th)+math.sqrt(th*th+1))
        c=1/math.sqrt(t*t+1); s=t*c
        for k in range(n):
            kp,kq=M[k][p],M[k][q]; M[k][p]=c*kp-s*kq; M[k][q]=s*kp+c*kq
        for k in range(n):
            pk,qk=M[p][k],M[q][k]; M[p][k]=c*pk-s*qk; M[q][k]=s*pk+c*qk
    return sorted((M[i][i] for i in range(n)), reverse=True)

random.seed(6)
n,p=6,12
phi=[[random.gauss(0,1) for _ in range(p)] for _ in range(n)]
K=matmul(phi,transpose(phi))
e=sym_eigs(K); L,mu=e[0],e[-1]
eta_star=2/(mu+L); rate=(L-mu)/(L+mu)
worst=lambda eta: max(abs(1-eta*l) for l in e)
print('eta*=',eta_star,' predicted rate=',rate,' worst@eta*=',worst(eta_star))
